      "category": "learning_objective",
      "rationale": "Mix uniform and detached hard-negative weights equally over valid positions, reducing weight concentration while retaining the pairwise softplus objective. This may improve validation HR@10 without changing sampling, architecture, inference, or training settings.",
      "edits": [
        {
          "find": "    weights = torch.softmax(valid_neg.detach(), dim=0)\n",
